/// Simplified -> Traditional (Taiwan) conversion for translator output (pure logic, no dependency).
///
/// Phone twin of desktop `translate.zh_convert(text, "tw")`, which Hy-MT2 output goes through on
/// desktop (`hymt.HyMtTranslator.translate`): OpenCC s2twp plus the same `_KEEP` shields and the
/// 妳 -> 你 rule. Tables come from the same OpenCC dictionaries (`s2tw_data.dart`, generated by
/// `tool/gen_s2tw_data.py`). Steps, as in OpenCC's s2twp chain:
///   1. STPhrases / STCharacters by forward maximum matching (longest phrase first);
///   2. TWPhrases (Taiwan wording, 软件 -> 軟體) on the result, again longest match first;
///   3. TWVariants (Taiwan glyphs, 裏 -> 裡) per character.
library;

import 's2tw_data.dart';

/// Desktop `translate._KEEP`: phrases s2twp would change to a wrong Taiwan term (通过 -> 透過,
/// 支持 -> 支援, passive 被发 -> 被髮, 家具有 -> 傢俱有, 连接 -> 連線) are shielded with a private-use
/// placeholder and restored to the plain Traditional form.
const List<(String, String)> _keep = [
  ('通过', '通過'),
  ('支持', '支持'),
  ('被发', '被發'),
  ('家具有', '家具有'),
  ('连接', '連接'),
];

class _Table {
  _Table(this.map) : maxLen = map.keys.fold(1, (m, k) => k.length > m ? k.length : m);

  factory _Table.parse(String data) => _Table({
        for (final e in data.split(' '))
          if (e.isNotEmpty) e.substring(0, e.indexOf('=')): e.substring(e.indexOf('=') + 1),
      });

  final Map<String, String> map;
  final int maxLen; // in UTF-16 code units, like the keys

  /// Longest-match-first replacement from left to right; unmatched text is copied unchanged
  /// (a surrogate pair is copied as one unit).
  String apply(String text, [String Function(String ch)? fallback]) {
    final out = StringBuffer();
    var i = 0;
    while (i < text.length) {
      String? hit;
      var n = text.length - i < maxLen ? text.length - i : maxLen;
      for (; n > 1 && hit == null; n--) {
        hit = map[text.substring(i, i + n)];
        if (hit != null) {
          out.write(hit);
          i += n;
        }
      }
      if (hit != null) continue;
      final width = _isHighSurrogate(text.codeUnitAt(i)) && i + 1 < text.length ? 2 : 1;
      final ch = text.substring(i, i + width);
      out.write(map[ch] ?? (fallback == null ? ch : fallback(ch)));
      i += width;
    }
    return out.toString();
  }

  static bool _isHighSurrogate(int u) => u >= 0xD800 && u <= 0xDBFF;
}

Map<String, String> _charMap() {
  final src = s2twSources.runes.toList();
  final dst = s2twTargets.runes.toList();
  assert(src.length == dst.length);
  return {
    for (var i = 0; i < src.length; i++) String.fromCharCode(src[i]): String.fromCharCode(dst[i]),
  };
}

final Map<String, String> _chars = _charMap();
final _Table _phrases = _Table.parse(s2twPhrases);
final _Table _twPhrases = _Table.parse(s2twTwPhrases);
final _Table _twVariants = _Table.parse(s2twTwVariants);

/// Converts Simplified Chinese to Traditional Chinese with Taiwan wording (OpenCC s2twp + desktop
/// fixes). Traditional input is returned unchanged except for Taiwan variants/wording.
String toTraditionalTw(String text) {
  if (text.isEmpty) return text;
  text = text.replaceAll('妳', '你'); // desktop: always the neutral 你
  for (var i = 0; i < _keep.length; i++) {
    final ph = String.fromCharCode(0xE000 + i);
    text = text.replaceAll(_keep[i].$1, ph).replaceAll(_keep[i].$2, ph);
  }
  var out = _phrases.apply(text, (ch) => _chars[ch] ?? ch);
  out = _twPhrases.apply(out);
  out = _twVariants.apply(out);
  for (var i = 0; i < _keep.length; i++) {
    out = out.replaceAll(String.fromCharCode(0xE000 + i), _keep[i].$2);
  }
  return out;
}
